CREATE FUNCTION public.claim_profile_password_attempt(_session uuid,_owner uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row public.profile_session_access; BEGIN SELECT * INTO row FROM public.profile_session_access WHERE session_id=_session AND user_id=_owner AND restricted FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; IF row.password_window_at < now()-interval '15 minutes' THEN UPDATE public.profile_session_access SET password_failures=1,password_window_at=now() WHERE session_id=_session; RETURN true; END IF; IF row.password_failures>=5 THEN RETURN false; END IF; UPDATE public.profile_session_access SET password_failures=password_failures+1 WHERE session_id=_session; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.claim_profile_password_attempt(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_profile_password_attempt(uuid,uuid) TO service_role;
CREATE FUNCTION public.restore_profile_staff_scope(_session uuid,_owner uuid,_credential uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM private.app_credentials WHERE id=_credential AND owner_id=_owner AND account_number=1) OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_owner AND role::text IN ('admin','management','staff','moderator')) OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_owner AND role::text IN ('banned','rejected','pending')) OR EXISTS(SELECT 1 FROM public.password_change_required WHERE user_id=_owner) THEN RETURN false; END IF; UPDATE public.profile_session_access SET restricted=false,credential_id=_credential,password_failures=0,updated_at=now() WHERE session_id=_session AND user_id=_owner AND restricted; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.restore_profile_staff_scope(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.restore_profile_staff_scope(uuid,uuid,uuid) TO service_role;